-- ═══════════════════════════════════════════════════════════════════════
-- Kratisimo — ΔΕΔΟΜΕΝΑ ΕΠΙΔΕΙΞΗΣ (demo data) για screenshots / παρουσίαση
--
-- ⚠️  ΣΒΗΝΕΙ ΟΛΑ τα υπάρχοντα δεδομένα (χρήστες, υπηρεσίες, ραντεβού, κριτικές,
--     δώρα, ωράρια, άδειες) και βάζει καινούρια. ΔΕΝ αγγίζει το σχήμα ούτε το
--     flyway_schema_history. Από το business_settings αλλάζει ΜΟΝΟ την επιβράβευση.
--
-- ΔΕΝ είναι migration: ΜΗΝ το βάλεις στο db/migration (το Flyway θα το έτρεχε σε κάθε
-- νέα βάση). Τρέχει χειροκίνητα: pgAdmin → Query Tool → Open File → F5.
--
-- Όλες οι ημερομηνίες είναι ΣΧΕΤΙΚΕΣ με τη Δευτέρα της τρέχουσας εβδομάδας:
--   12 εβδομάδες ιστορικό (ολοκληρωμένα / ακυρωμένα) + τρέχουσα + 2 επόμενες.
--   Ξανατρέξ' το όποτε θες «φρέσκα» δεδομένα — πάντα θα υπάρχουν επερχόμενα ραντεβού.
--
-- Κωδικοί: admin@kratisimo.com / admin123
--          maria|giorgos|eleni|nikos|anna@kratisimo.com / employee123
--          <όλοι οι πελάτες>@example.com / customer123
--
-- Όλα τρέχουν σε ΕΝΑ transaction: αν κάτι αποτύχει, τίποτα δεν αλλάζει
-- (στο pgAdmin τρέξε μετά ένα σκέτο ROLLBACK; για να «ξεκολλήσει» η σύνδεση).
-- ═══════════════════════════════════════════════════════════════════════

BEGIN;

-- Ρολόι του script: «τώρα» + Δευτέρα της τρέχουσας εβδομάδας (ώρα Ελλάδας).
CREATE TEMP TABLE demo_clock ON COMMIT DROP AS
SELECT now() AS t0,
       date_trunc('week', now() AT TIME ZONE 'Europe/Athens')::date AS anchor;

-- (μέρες από τη Δευτέρα, λεπτά από τα μεσάνυχτα) → timestamptz σε ώρα Ελλάδας.
-- Προσωρινή συνάρτηση (pg_temp): χάνεται όταν κλείσει η σύνδεση, δεν μένει τίποτα στη βάση.
CREATE OR REPLACE FUNCTION pg_temp.demo_ts(d int, m int) RETURNS timestamptz
LANGUAGE sql STABLE AS $$
    SELECT ((c.anchor + d)::timestamp + make_interval(mins => m)) AT TIME ZONE 'Europe/Athens'
    FROM demo_clock c
$$;

TRUNCATE reviews, appointment_items, appointments, loyalty_rewards, time_off, working_hours,
         employee_services, employee_profiles, user_roles, users, services, service_categories
RESTART IDENTITY CASCADE;

-- Επιβράβευση: ενεργή, 5 επισκέψεις → 20%. (Ξεκίνησε πριν 8 εβδομάδες με 15% και
-- άλλαξε σε 20% πριν 3 — γι' αυτό υπάρχουν κερδισμένα δώρα και των δύο ποσοστών.)
UPDATE business_settings
SET loyalty_enabled = true, loyalty_visits_required = 5, loyalty_discount_percent = 20,
    setup_completed = true
WHERE id = 1;

