INSERT INTO services (id, category_id, name, description, duration_minutes, price, target_audience, active) VALUES
  (1, 1, 'Γυναικείο κούρεμα', 'Κούρεμα με λούσιμο, μάσκα και στέγνωμα.', 45, 28.00, 'WOMAN', true),
  (2, 1, 'Χτένισμα / Brushing', 'Λούσιμο και χτένισμα με πιστολάκι ή σίδερο.', 30, 18.00, 'WOMAN', true),
  (3, 1, 'Βαφή ρίζας', 'Κάλυψη ρίζας έως 3 εκ. με επαγγελματικές βαφές χωρίς αμμωνία.', 60, 38.00, 'WOMAN', true),
  (4, 1, 'Ολική βαφή', 'Βαφή σε όλο το μήκος, με διαβούλευση για την απόχρωση.', 90, 55.00, 'WOMAN', true),
  (5, 1, 'Ανταύγειες / Balayage', 'Φυσικό, «ήλιο-φωτισμένο» αποτέλεσμα με την τεχνική balayage.', 150, 95.00, 'WOMAN', true),
  (6, 1, 'Θεραπεία κερατίνης', 'Ισιωτική θεραπεία που διαρκεί έως 3 μήνες.', 120, 80.00, 'WOMAN', true),
  (7, 1, 'Παιδικό κούρεμα', 'Για παιδιά έως 12 ετών.', 20, 12.00, 'UNISEX', true),
  (8, 1, 'Περμανάντ', 'Κλασική περμανάντ για όγκο και μπούκλες.', 120, 60.00, 'WOMAN', false),
  (9, 2, 'Ανδρικό κούρεμα', 'Κούρεμα με ψαλίδι ή μηχανή, λούσιμο και styling.', 30, 15.00, 'MAN', true),
  (10, 2, 'Κούρεμα & γένια', 'Κούρεμα και πλήρης περιποίηση γενειάδας.', 45, 22.00, 'MAN', true),
  (11, 2, 'Περιποίηση γενειάδας', 'Σχηματισμός, τριμάρισμα και λάδι γενειάδας.', 20, 10.00, 'MAN', true),
  (12, 2, 'Ξύρισμα με ζεστή πετσέτα', 'Παραδοσιακό ξύρισμα με ξυράφι και ζεστή πετσέτα.', 30, 14.00, 'MAN', true),
  (13, 3, 'Manicure', 'Περιποίηση νυχιών και πετσάκι, με απλό βερνίκι.', 30, 14.00, 'UNISEX', true),
  (14, 3, 'Ημιμόνιμο manicure', 'Ημιμόνιμο βερνίκι που διαρκεί 2–3 εβδομάδες.', 45, 22.00, 'WOMAN', true),
  (15, 3, 'Pedicure', 'Πλήρης περιποίηση ποδιών.', 45, 25.00, 'UNISEX', true),
  (16, 4, 'Καθαρισμός προσώπου', 'Βαθύς καθαρισμός με ατμό, απολέπιση και μάσκα.', 60, 40.00, 'UNISEX', true),
  (17, 4, 'Περιποίηση φρυδιών', 'Σχηματισμός φρυδιών με κερί ή τσιμπιδάκι.', 15, 8.00, 'UNISEX', true);

-- ─── Υπάλληλοι (ο Στέλιος είναι αρχειοθετημένος: έφυγε πριν 7 εβδομάδες) ───
INSERT INTO employee_profiles (id, user_id, bio, photo_url, active) VALUES
  (1, 2, 'Senior hair stylist με 12 χρόνια εμπειρίας. Ειδικεύεται στις βαφές και στο balayage — λατρεύει τα φυσικά, φωτεινά αποτελέσματα.', 'https://randomuser.me/api/portraits/women/44.jpg', true),
  (2, 3, 'Barber με πάθος για τα κλασικά κουρέματα και τα fades. Το ξύρισμα με ζεστή πετσέτα είναι η σπεσιαλιτέ του.', 'https://randomuser.me/api/portraits/men/32.jpg', true),
  (3, 4, 'Αισθητικός και nail artist. Φροντίζει νύχια και επιδερμίδα με προσοχή στη λεπτομέρεια και στην υγιεινή.', 'https://randomuser.me/api/portraits/women/68.jpg', true),
  (4, 5, 'Barber και stylist. Δουλεύει σε σπαστό ωράριο ώστε να εξυπηρετεί και πρωί και απόγευμα μετά τη δουλειά.', 'https://randomuser.me/api/portraits/men/75.jpg', true),
  (5, 6, 'Hair stylist με έμφαση στα γυναικεία κουρέματα και στα χτενίσματα για εκδηλώσεις. Κάνει και manicure.', 'https://randomuser.me/api/portraits/women/65.jpg', true),
  (6, 7, 'Barber. Αποχώρησε από την ομάδα.', 'https://randomuser.me/api/portraits/men/52.jpg', false);

