-- Περνούν από προσωρινό πίνακα: τα μελλοντικά μπαίνουν ΜΟΝΟ αν η ώρα τους δεν έχει
-- περάσει τη στιγμή που τρέχει το script (αλλιώς θα ήταν «επιβεβαιωμένα στο παρελθόν»).
CREATE TEMP TABLE demo_appt (
    id int, customer_id bigint, guest_name text, guest_phone text, employee_id bigint,
    d int, m int, dur int, status text, subtotal numeric(8,2), disc_pct int, disc_amt numeric(8,2),
    lead_min int, cancel_before int, cancel_reason text, stamp boolean, reward_id bigint
) ON COMMIT DROP;

