INSERT INTO appointments (id, customer_id, guest_name, guest_phone, employee_id, starts_at, ends_at,
                          status, total_price, total_duration_minutes, created_at, cancelled_at,
                          cancellation_reason, discount_percent, discount_amount, loyalty_stamp,
                          loyalty_reward_id)
SELECT a.id, a.customer_id, a.guest_name, a.guest_phone, a.employee_id,
       x.starts, x.starts + make_interval(mins => a.dur),
       a.status, a.subtotal - a.disc_amt, a.dur,
       CASE WHEN a.d < 0 THEN x.starts - make_interval(mins => a.lead_min)
            ELSE c.t0 - make_interval(mins => 60 + (a.id * 37) % 1140) END,   -- κράτηση «πρόσφατα»
       CASE WHEN a.status = 'CANCELLED' THEN x.starts - make_interval(mins => a.cancel_before) END,
       a.cancel_reason, a.disc_pct, a.disc_amt, a.stamp, a.reward_id
FROM demo_appt a
CROSS JOIN demo_clock c
CROSS JOIN LATERAL (SELECT pg_temp.demo_ts(a.d, a.m) AS starts) x
WHERE a.d < 0 OR x.starts > c.t0
ORDER BY a.id;

-- ─── Υπηρεσίες κάθε ραντεβού (snapshots τιμής/διάρκειας, D6) ───
CREATE TEMP TABLE demo_item (appt int, service_id bigint, price numeric(8,2), dur int, ord int) ON COMMIT DROP;
