INSERT INTO appointment_items (appointment_id, service_id, price_snapshot, duration_snapshot, sort_order)
SELECT i.appt, i.service_id, i.price, i.dur, i.ord
FROM demo_item i
WHERE EXISTS (SELECT 1 FROM appointments a WHERE a.id = i.appt)
ORDER BY i.appt, i.ord;

