INSERT INTO reviews (appointment_id, rating, comment, created_at)
SELECT r.appt, r.rating, r.comment,
       LEAST(a.ends_at + make_interval(mins => r.after_min), c.t0 - interval '1 hour')
FROM demo_review r
JOIN appointments a ON a.id = r.appt
CROSS JOIN demo_clock c
ORDER BY r.appt;

-- ─── Οι μετρητές IDENTITY συνεχίζουν μετά τα ids που δώσαμε ρητά ───
SELECT setval(pg_get_serial_sequence('users', 'id'), (SELECT max(id) FROM users));
SELECT setval(pg_get_serial_sequence('service_categories', 'id'), (SELECT max(id) FROM service_categories));
SELECT setval(pg_get_serial_sequence('services', 'id'), (SELECT max(id) FROM services));
SELECT setval(pg_get_serial_sequence('employee_profiles', 'id'), (SELECT max(id) FROM employee_profiles));
SELECT setval(pg_get_serial_sequence('appointments', 'id'), (SELECT max(id) FROM demo_appt));
SELECT setval(pg_get_serial_sequence('loyalty_rewards', 'id'), (SELECT max(id) FROM loyalty_rewards));

COMMIT;

-- ─── Σύνοψη ───
SELECT 'Πελάτες' AS τι, count(*)::text AS πόσα FROM user_roles WHERE role = 'CUSTOMER'
UNION ALL SELECT 'Ραντεβού ' || status, count(*)::text FROM appointments GROUP BY status
UNION ALL SELECT 'Κριτικές', count(*)::text FROM reviews
UNION ALL SELECT 'Δώρα επιβράβευσης', count(*)::text FROM loyalty_rewards;
